//! Refill-bounded GIF island; original allocation/stdio/SjLj and exits retained.
use crate::{Environment,cpu::CpuContext,abi::GuestFunction,mem::{ConstPtr,MutPtr}};
use crate::gif_island_kernel as k;use crate::native_batch_kernel::Outcome;
use crate::dyld::{export_c_func,FunctionExports};
#[derive(Default)]pub(crate)struct State{original:Option<GuestFunction>,prefix:[u8;8],disabled:bool,validating:bool,corpus:bool,active:Option<(usize,u32)>,captured:Option<CpuContext>,total:u64,shadows:[u64;2],calls:[u64;2],fast:[u64;2]}
fn event(kind:&str,class:usize,count:u64){crate::diagnostics::event(&format!("{{\"event\":\"gif_island_native\",\"kind\":\"{kind}\",\"class\":{class},\"count\":{count}}}"));}
fn equal(a:CpuContext,b:CpuContext)->bool{a.regs==b.regs&&a.extregs==b.extregs&&a.cpsr==b.cpsr&&a.fpscr==b.fpscr}
fn go(e:&mut Environment,a:u32){e.cpu.branch(GuestFunction::from_addr_with_thumb_bit(a|1));}
fn tail(e:&mut Environment){e.cpu.branch(e.libc_state.gif_island.original.unwrap());}
fn capture(e:&mut Environment,exit:u32){let s=&e.libc_state.gif_island;if s.active==Some((e.current_thread,e.cpu.regs()[13])){let mut c=e.cpu.visible_context();c.regs[15]=exit;c.cpsr|=0x20;e.libc_state.gif_island.captured=Some(c);e.cpu.branch(e.dyld.return_to_host_routine());}else{go(e,exit);}}
fn refill(e:&mut Environment){capture(e,crate::gif_island_generated::EXITS[0])}fn row(e:&mut Environment){capture(e,crate::gif_island_generated::EXITS[1])}
fn predict(e:&Environment)->Option<Outcome>{let mut c=e.cpu.visible_context();c.regs[15]=0x287978;c.cpsr|=0x20;k::calculate(k::snapshot(&e.mem,c,e.libc_state.peggle_native_batch.code_guard())?)}
fn compare(e:&mut Environment,p:&Outcome)->bool{e.libc_state.gif_island.active=Some((e.current_thread,e.cpu.regs()[13]));e.libc_state.gif_island.captured=None;tail(e);e.run_call();let actual=e.libc_state.gif_island.captured.take();e.libc_state.gif_island.active=None;let Some(c)=actual else{panic!("GIF private original missed owned exit");};e.cpu.restore_visible_context(c);equal(c,p.context)&&p.regions.iter().all(|r|e.mem.bytes_at(ConstPtr::<u8>::from_bits(r.address),r.bytes.len()as u32)==&r.bytes[..])}
fn disable(e:&mut Environment,why:&str){e.libc_state.gif_island.disabled=true;let prefix=e.libc_state.gif_island.prefix;e.mem.bytes_at_mut(MutPtr::<u8>::from_bits(0x287978),8).copy_from_slice(&prefix);e.cpu.invalidate_cache_range(0x287978,8);event(why,255,0);}
fn corpus(e:&mut Environment)->bool{let saved=e.cpu.visible_context();let Some(a)=e.mem.try_alloc(65536).map(|p|p.cast::<u8>())else{return false;};e.libc_state.gif_island.validating=true;let mut passed=0;for n in 0..128{let c=k::seed(&mut e.mem,saved,a.to_bits(),n);e.cpu.restore_visible_context(c);let Some(p)=predict(e)else{break;};if !compare(e,&p){break;}passed+=1;}e.cpu.restore_visible_context(saved);e.mem.free(a.cast());e.libc_state.gif_island.validating=false;event(if passed==128{"corpus_passed"}else{"corpus_failed"},255,passed);passed==128}
fn island(e:&mut Environment){let s=&e.libc_state.gif_island;if s.disabled||s.validating||s.active.is_some()||!k::profitable(&e.mem,e.cpu.visible_context()){return tail(e);}let Some(p)=predict(e)else{return tail(e);};let sp=e.cpu.regs()[13];let before=e.mem.read(ConstPtr::<u32>::from_bits(sp+0xe4));let after=u32::from_le_bytes(p.regions[0].bytes[0xe4..0xe8].try_into().unwrap());if after.checked_sub(before).is_none_or(|n|n<16){return tail(e);}let class=usize::from(p.context.regs[15]==0x287b50);
 if !s.corpus{if !corpus(e){disable(e,"disabled_after_corpus_failure");return tail(e);}e.libc_state.gif_island.corpus=true;}
 let s=&mut e.libc_state.gif_island;s.calls[class]+=1;
 if s.total<128||s.shadows[class]<16||s.calls[class]%1024==0{if !compare(e,&p){disable(e,"disabled_after_real_mismatch");}else{let s=&mut e.libc_state.gif_island;s.total+=1;s.shadows[class]+=1;if s.total==128{event("real_global_gate_passed",255,128);}if s.shadows[class]==16{event("real_class_gate_passed",class,16);}}let exit=e.cpu.regs()[15];go(e,exit);return;}
 for r in &p.regions{if r.writable{e.mem.bytes_at_mut(MutPtr::<u8>::from_bits(r.address),r.bytes.len()as u32).copy_from_slice(&r.bytes);}}e.cpu.restore_visible_context(p.context);go(e,p.context.regs[15]);let s=&mut e.libc_state.gif_island;s.fast[class]+=1;let n=s.fast[class];if n==1||n%65536==0{event("fast_calls",class,n);}
}
const FUNCTIONS:FunctionExports=&[export_c_func!(island()),export_c_func!(refill()),export_c_func!(row())];
pub(crate)fn install_entries(mem:&mut crate::mem::Mem,dyld:&mut crate::dyld::Dyld,libc:&mut crate::libc::State){let a=0x287978;let body=mem.bytes_at(ConstPtr::<u8>::from_bits(a),472).to_vec();let tr=mem.alloc(480).cast::<u8>();mem.bytes_at_mut(tr,472).copy_from_slice(&body);let host=dyld.create_guest_function(mem,FUNCTIONS[0].0,FUNCTIONS[0].1);let refill=dyld.create_guest_function(mem,FUNCTIONS[1].0,FUNCTIONS[1].1);let row=dyld.create_guest_function(mem,FUNCTIONS[2].0,FUNCTIONS[2].1);for(o,t)in[(36,refill.addr_with_thumb_bit()),(472,row.addr_with_thumb_bit())]{mem.write(MutPtr::<u32>::from_bits(tr.to_bits()+o),0xf000f8dfu32);mem.write(MutPtr::<u32>::from_bits(tr.to_bits()+o+4),t);}for(a,n)in[(tr.to_bits(),480),(host.addr_without_thumb_bit(),8),(refill.addr_without_thumb_bit(),8),(row.addr_without_thumb_bit(),8)]{crate::peggle_native_batch::protect_code(libc,a,n);}libc.gif_island=State{original:Some(GuestFunction::from_addr_with_thumb_bit(tr.to_bits()|1)),prefix:body[..8].try_into().unwrap(),..State::default()};mem.write(MutPtr::<u32>::from_bits(a),0xf000f8dfu32);mem.write(MutPtr::<u32>::from_bits(a+4),host.addr_with_thumb_bit());event("guarded_island_installed",255,0);}

pub(crate)fn install(verified:bool,bins:&[crate::mach_o::MachO],mem:&mut crate::mem::Mem,dyld:&mut crate::dyld::Dyld,libc:&mut crate::libc::State){use digest::Digest;if !verified||std::env::var("PEGGLE_HD_GIF_ISLAND_NATIVE").as_deref()!=Ok("1"){return;}if bins.first().and_then(|b|b.exported_symbols.get("__Z11GetGIFImageRKSs"))!=Some(&0x287071)||!mem.is_mapped_range(0x287070,3300)||format!("{:x}",sha1::Sha1::digest(mem.bytes_at(ConstPtr::<u8>::from_bits(0x287070),3300)))!="2bb1a1fa2b7035e775d94e30d05fc01633b7c791"{event("image_guard_rejected",255,0);return;}install_entries(mem,dyld,libc);}
